type Tab = 'sim' | 'learn' | 'experiments' | 'compare' | 'benchmark' | 'sensitivity' | 'dimensional' | 'reports' | 'jobs' | 'science';

/** Keep navigation functional when a lazily loaded laboratory chunk cannot be fetched. */
class ModuleErrorBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() {
    if (this.state.failed) return <section className="panel module-fallback" role="alert">
      <CircleHelp size={24}/><h2>Laboratuvar yüklenemedi</h2>
      <p>Modül dosyası alınamadı. İnternet veya yerel sunucu bağlantısını kontrol edip sayfayı yenile.</p>
      <button className="button-primary" onClick={() => window.location.reload()}><RotateCcw size={16}/> Sayfayı yeniden yükle</button>
    </section>;
    return this.props.children;
  }
}

function ModuleLoading() {
  return <section className="panel module-fallback" role="status" aria-live="polite">
    <span className="module-loading-spinner" aria-hidden="true"/>
    <strong>Laboratuvar hazırlanıyor…</strong>
    <p>Yalnızca açtığın modülün arayüzü yükleniyor; deneylerin ve arşivin değişmiyor.</p>
  </section>;
}
const DEFAULT: Config = { algorithm:'fa', objective:'rastrigin', population_size:24, iterations:90, alpha:.18, beta0:1, gamma:.12, seed:42, inertia_weight:.72, cognitive_coefficient:1.49, social_coefficient:1.49, velocity_limit:.2, abc_limit:30, cs_discovery_rate:.25, cs_step_scale:.08, cs_levy_exponent:1.5, mfo_spiral_b:1.0, gwo_initial_a:2.0, woa_initial_a:2.0, woa_spiral_b:1.0, woa_spiral_probability:0.5, ba_frequency_min:0, ba_frequency_max:2, ba_initial_loudness:.9, ba_loudness_decay:.9, ba_initial_pulse_rate:.5, ba_pulse_growth:.9, ssa_c1_initial:2.0, sma_restart_probability:0.03, iwo_max_population:60, iwo_min_seeds:0, iwo_max_seeds:5, iwo_sigma_initial:1.5, iwo_sigma_final:.02, iwo_modulation_index:3, sa_initial_temperature:10, sa_cooling_rate:0.95, sa_step_scale:0.10, gsa_initial_gravity:100, gsa_decay:20, gsa_epsilon:.01, de_mutation_factor:.75, de_crossover_rate:.90 };
const GROUPS = ['Böcek ve sürü','Yırtıcı ve deniz','Bitki ve biyoloji','Fizik ve evrim'];
const ABBREV: Record<string,string> = {fa:'FA',pso:'PSO',abc:'ABC',aco:'ACO',cs:'CS',mfo:'MFO',gwo:'GWO',woa:'WOA',ba:'BA',ssa:'SSA',sma:'SMA',iwo:'IWO',sa:'SA',gsa:'GSA',de:'DE'};
const SYMBOLS: Record<string,string> = {fa:'✺',pso:'◉',abc:'⬡',aco:'⌁',cs:'↗',mfo:'❈',gwo:'♜',woa:'◌',ba:'⌁',ssa:'≈',sma:'◈',iwo:'✳',sa:'♨',gsa:'◎',de:'⟡'};
const format = (v:number,d=4)=>numberFmt(v,d);

function ParameterSlider({title, hint, value, min, max, step, onChange, decimals=2}: {title:string;hint:string;value:number;min:number;max:number;step:number;onChange:(n:number)=>void;decimals?:number}) {
  return <div className="field-group">
    <label className="field-top"><span>{title}<small>{hint}</small></span><strong>{value.toFixed(decimals)}</strong></label>
    <input aria-label={title} type="range" min={min} max={max} step={step} value={value} onChange={e=>onChange(Number(e.target.value))}/>
    <div className="field-range"><span>{min}</span><span>{max}</span></div>
  </div>;
}

function Convergence({run,index}:{run:Run|null;index:number}) {
  if(!run) return <div className="empty-chart"><Activity size={25}/> İlk çalıştırmadan sonra yakınsama grafiği görünecek.</div>;
  const values=run.frames.map(f=>f.best_so_far);
  const max=Math.max(...values,1), min=Math.min(...values,0);
  const W=620,H=154, left=45,right=10,top=12,bottom=28;
  const x=(i:number)=>left+i/Math.max(1,values.length-1)*(W-left-right);
  const y=(v:number)=>top+(max-v)/(max-min||1)*(H-top-bottom);
  const path=values.map((v,i)=>`${i===0?'M':'L'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');
  const shownPath=values.slice(0,index+1).map((v,i)=>`${i===0?'M':'L'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');
  return <svg className="convergence-svg" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="İterasyona göre en iyi amaç fonksiyonu değeri">
    <defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#67dfc2" stopOpacity=".22"/><stop offset="100%" stopColor="#67dfc2" stopOpacity="0"/></linearGradient></defs>
    {[0,.25,.5,.75,1].map(k=><g key={k}><line x1={left} y1={top+k*(H-top-bottom)} x2={W-right} y2={top+k*(H-top-bottom)} stroke="rgba(177,216,220,.12)" strokeDasharray="3 6"/><text x="6" y={top+k*(H-top-bottom)+4} fill="#8397a8" fontSize="10">{format(max-k*(max-min),1)}</text></g>)}
    <path d={path} stroke="rgba(103,223,194,.20)" strokeWidth="1.5" fill="none"/>
    <path d={`${shownPath} L${x(index)},${H-bottom} L${left},${H-bottom} Z`} fill="url(#chartfill)"/>
    <path d={shownPath} stroke="#6ee7ce" strokeWidth="2.7" strokeLinejoin="round" strokeLinecap="round" fill="none"/>
    <line x1={x(index)} x2={x(index)} y1={top} y2={H-bottom} stroke="#c7f8e8" opacity=".3" strokeDasharray="3 3"/>
    <circle cx={x(index)} cy={y(values[index])} r="4.3" fill="#83f5d8" stroke="#133d41" strokeWidth="2"/>
    {[0,.25,.5,.75,1].map(k=><text key={k} x={x(Math.round(k*(values.length-1)))} y={H-6} fill="#8397a8" textAnchor="middle" fontSize="10">{Math.round(k*(values.length-1))}</text>)}
  </svg>;
}

function SaTemperatureChart({run,index}:{run:Run;index:number}){
  const W=620,H=132,L=46,R=12,T=12,B=22;
  const frames=run.frames;
  const logValues=frames.map(f=>Math.log(Math.max(f.sa_temperature??1e-30,1e-30)));
  const min=Math.min(...logValues),max=Math.max(...logValues);
  const x=(i:number)=>L+i/Math.max(1,frames.length-1)*(W-L-R);
  const y=(v:number)=>T+(max-v)/Math.max(max-min,1e-12)*(H-T-B);
  const segment=logValues.slice(0,index+1).map((v,i)=>`${i===0?'M':'L'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');
  return <svg className="convergence-svg" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="SA sıcaklık düşüş eğrisi ve kabul edilen ya da reddedilen adaylar">
    {[0,.5,1].map(k=><g key={k}><line x1={L} x2={W-R} y1={T+k*(H-T-B)} y2={T+k*(H-T-B)} stroke="rgba(177,216,220,.14)" strokeDasharray="3 6"/><text x="3" y={T+k*(H-T-B)+4} fill="#8397a8" fontSize="10">{Math.exp(max-k*(max-min)).toFixed(2)}</text></g>)}
    <path d={segment} stroke="#82dded" strokeWidth="2.5" fill="none" strokeLinejoin="round"/>
    {frames.slice(1,index+1).filter(f=>f.iteration%Math.max(1,Math.floor(frames.length/70))===0).map(f=><circle key={f.iteration} cx={x(f.iteration)} cy={y(logValues[f.iteration])} r="2.7" fill={f.sa_last_accepted?'#a6efb0':'#ed9e81'} opacity=".9"/>)}
    <circle cx={x(index)} cy={y(logValues[index])} r="4" stroke="#12373a" strokeWidth="1.5" fill="#83f5d8"/>
    <text x={L} y={H-4} fill="#8397a8" fontSize="10">0</text><text x={W-R} y={H-4} textAnchor="end" fill="#8397a8" fontSize="10">{frames.length-1} adım</text>
  </svg>;
}

function ModelExplanation({algorithm}:{algorithm: 'fa'|'pso'|'abc'}) {
  if(algorithm==='abc') return <div className="model-grid"><div><span className="label-overline">YENİ KAYNAK ADAYI</span><div className="formula small-formula">vᵢⱼ = xᵢⱼ + φ(xᵢⱼ − xₖⱼ)</div><p>Rastgele seçilen bir koordinat, farklı bir kaynağın konumuna göre değiştirilir. φ ∈ [−1, 1]. Daha iyi aday kabul edilir.</p></div><div><span className="label-overline">GÖZLEMCİ SEÇİMİ</span><div className="formula small-formula">pᵢ = fitᵢ / Σ fitₖ</div><p>Besin kalitesi yüksek kaynaklar daha fazla gözlemci çeker. Başarısız denemeler limit değerine ulaşınca bir kaynak keşifçi tarafından yenilenir.</p></div></div>;
  if(algorithm==='pso') return <div className="model-grid"><div><span className="label-overline">HIZ GÜNCELLEMESİ</span><div className="formula small-formula">v ← wv + c₁r₁(pBest − x) + c₂r₂(gBest − x)</div><p>Atalet, bireysel bellek ve sürü bilgisinden oluşan yeni hız hesaplanır.</p></div><div><span className="label-overline">KONUM GÜNCELLEMESİ</span><div className="formula">x ← x + v</div><p>Hız sınırlandırılır ve pozisyon arama sınırlarına kırpılır; taşan eksendeki hız sıfırlanır.</p></div></div>;
  return <div className="model-grid">
    <div><span className="label-overline">ÇEKİCİLİK MODELİ</span><div className="formula">β(r) = β₀ · e<sup>−γr²</sup></div><p>Ajanlar arası mesafe arttıkça çekicilik azalır. Gamma bu azalma hızını belirler.</p></div>
    <div><span className="label-overline">HAREKET DENKLEMİ</span><div className="formula small-formula">x<sub>i</sub> ← x<sub>i</sub> + β(r)(x<sub>j</sub> − x<sub>i</sub>) + αε</div><p>Daha parlak bireylere yönelim ve kontrollü rassal hareket birleştirilir.</p></div>
  </div>;
}

export default function App(){
  const [catalog,setCatalog]=useState<Catalog|null>(null);
  const [activeId,setActiveId]=useState('fa');
  const [tab,setTab]=useState<Tab>('sim');
  const [search,setSearch]=useState('');
  const [config,setConfig]=useState<Config>(DEFAULT);
  const [usedConfig,setUsedConfig]=useState<Config|null>(null);
  const [run,setRun]=useState<Run|null>(null);
  const [runs,setRuns]=useState<Run[]>([]);
  const [index,setIndex]=useState(0);
  const [playing,setPlaying]=useState(false);
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState<string|null>(null);
  const [speed,setSpeed]=useState(1);
  const [selectedId,setSelectedId]=useState<number|null>(null);
  const [trails,setTrails]=useState(true);
  const [showTargets,setShowTargets]=useState(true);
  const [sidebarOpen,setSidebarOpen]=useState(false);
  const [paramsOpen,setParamsOpen]=useState(false);
  const menuButtonRef=useRef<HTMLButtonElement>(null);
  const menuCloseRef=useRef<HTMLButtonElement>(null);
  const selectedAlgorithm=catalog?.algorithms.find(x=>x.id===activeId);
  const ready=selectedAlgorithm?.status==='ready'||activeId==='fa';
  const isPso=activeId==='pso';
  const isAbc=activeId==='abc';
  const isCs=activeId==='cs';
  const isMfo=activeId==='mfo';
  const isGwo=activeId==='gwo';
  const isWoa=activeId==='woa';
  const isBa=activeId==='ba';
  const isSsa=activeId==='ssa';
  const isSma=activeId==='sma';
  const isIwo=activeId==='iwo';
  const isSa=activeId==='sa';
  const isGsa=activeId==='gsa';
  const isDe=activeId==='de';
  const currentRun=run?.algorithm===activeId?run:null;
  const frame=currentRun?.frames[Math.min(index,currentRun.frames.length-1)] ?? null;
  const stale=!!usedConfig && JSON.stringify(config)!==JSON.stringify(usedConfig);
  const filtered=useMemo(()=>catalog?.algorithms.filter(a=>`${a.name} ${a.english} ${a.id}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))) ?? [],[catalog,search]);

  useEffect(()=>{
    const controller=new AbortController();
    getCatalog().then(setCatalog).catch(e=>setError(e.message));
    // The first screen opens with a real, seeded simulation rather than fabricated demo data.
    runSimulation(DEFAULT,controller.signal).then(result=>{
      setRun(result);setRuns([result]);setUsedConfig({...DEFAULT});setIndex(0);setPlaying(true);
    }).catch(e=>{if(e.name!=='AbortError')setError(e.message)});
    return ()=>controller.abort();
  },[]);
  useEffect(()=>{
    if(!playing||!run||tab!=='sim'||!ready) return;
    const timer=window.setInterval(()=>setIndex(prev=>{
      if(prev+1>=run.frames.length){setPlaying(false);return run.frames.length-1}
      return prev+1;
    }),Math.round(145/speed));
    return ()=>window.clearInterval(timer);
  },[playing,run,speed,tab,ready]);
  useEffect(() => {
    if (!sidebarOpen) return;
    menuCloseRef.current?.focus();
    const onEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setSidebarOpen(false);
        menuButtonRef.current?.focus();
      }
    };
    window.addEventListener('keydown', onEscape);
    return () => window.removeEventListener('keydown', onEscape);
  }, [sidebarOpen]);
  const closeSidebar = () => {
    if (sidebarOpen) {
      setSidebarOpen(false);
      window.requestAnimationFrame(() => document.getElementById('main-content')?.focus());
    }
  };
  const update=<K extends keyof Config>(key:K,value:Config[K])=>setConfig(prev=>({...prev,[key]:value}));
  async function start(){
    setLoading(true);setError(null);setPlaying(false);setSelectedId(null);
    try{
      const result=await runSimulation(config);
      setRun(result);setUsedConfig({...config});setRuns(prev=>[result,...prev].slice(0,6));
      setIndex(0);setPlaying(true);setTab('sim');
    }catch(e){setError(e instanceof Error?e.message:'Beklenmeyen hata');}
    finally{setLoading(false)}
  }
  const choose=(algorithm:Algorithm)=>{
    setActiveId(algorithm.id);setPlaying(false);closeSidebar();setSelectedId(null);setIndex(0);
    if(algorithm.status==='ready'){
      const existing=runs.find(r=>r.algorithm===algorithm.id)??null;
      setRun(existing);setUsedConfig(null);if(algorithm.id!=='aco')setConfig(prev=>({...prev,algorithm:algorithm.id as Config['algorithm']}));
    }
    setTab(algorithm.status==='ready'?'sim':'learn');
  };
  const exportCsv=()=>{if(currentRun)downloadCsv(currentRun.frames.map(f=>({iteration:f.iteration,best_so_far:f.best_so_far,current_best:f.current_best,mean_fitness:f.mean_fitness,diversity:f.diversity,function_evaluations:f.function_evaluations})),`${currentRun.algorithm}-${currentRun.objective}-${currentRun.seed}.csv`)};

  return <div className="app-shell">
    <a className="skip-link" href="#main-content">Ana içeriğe geç</a>
    <aside id="lab-sidebar" aria-label="Laboratuvar menüsü" className={`sidebar ${sidebarOpen?'sidebar-open':''}`}>
      <div className="brand"><div className="brand-icon"><FlaskConical size={24}/></div><div><strong>METAHEURISTIC<span>LAB</span></strong><small>OPTIMIZATION WORKSPACE</small></div><button ref={menuCloseRef} className="mobile-close" aria-label="Menüyü kapat" onClick={()=>{setSidebarOpen(false);menuButtonRef.current?.focus();}}><X size={20}/></button></div>
      <div className="sidebar-section-title">LABORATUVAR</div>
      <nav className="primary-nav" aria-label="Birincil gezinme">
        <button className={tab==='sim'?'current':''} onClick={()=>{setTab('sim');closeSidebar()}}><Activity size={17}/> Simülasyon Laboratuvarı <span className="nav-hot-dot"/></button>
        <button className={tab==='compare'?'current':''} onClick={()=>{setTab('compare');setPlaying(false);closeSidebar()}}><GitBranch size={17}/> Karşılaştırma Laboratuvarı <span className="nav-hot-dot"/></button>
        <button className={tab==='benchmark'?'current':''} onClick={()=>{setTab('benchmark');setPlaying(false);closeSidebar()}}><FlaskConical size={17}/> Benchmark Stüdyosu <span className="nav-hot-dot"/></button>
        <button className={tab==='sensitivity'?'current':''} onClick={()=>{setTab('sensitivity');setPlaying(false);closeSidebar()}}><SlidersHorizontal size={17}/> Parametre Duyarlılığı <span className="nav-hot-dot"/></button>
        <button className={tab==='dimensional'?'current':''} onClick={()=>{setTab('dimensional');setPlaying(false);closeSidebar()}}><FlaskConical size={17}/> Yüksek Boyut Laboratuvarı <span className="nav-hot-dot"/></button>
        <button className={tab==='jobs'?'current':''} onClick={()=>{setTab('jobs');setPlaying(false);closeSidebar()}}><Clock3 size={17}/> Deney Kuyruğu <span className="nav-hot-dot"/></button>
        <button className={tab==='reports'?'current':''} onClick={()=>{setTab('reports');setPlaying(false);closeSidebar()}}><FileText size={17}/> Akademik Raporlar <span className="nav-hot-dot"/></button>
        <button className={tab==='science'?'current':''} onClick={()=>{setTab('science');setPlaying(false);closeSidebar()}}><ShieldCheck size={17}/> Bilimsel Doğrulama <span className="nav-hot-dot"/></button>
        <button className={tab==='learn'?'current':''} onClick={()=>{setTab('learn');closeSidebar()}}><BookOpen size={17}/> Algoritma Rehberi</button>
        <button className={tab==='experiments'?'current':''} onClick={()=>{setTab('experiments');closeSidebar()}}><Layers3 size={17}/> Son Deneyler <small>{runs.length}</small></button>
      </nav>
      <div className="sidebar-section-heading"><span>ALGORİTMA KÜTÜPHANESİ</span><span>{catalog?.algorithms.length??15}</span></div>
      <div className="search-box"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Algoritma ara..." aria-label="Algoritma ara"/></div>
      <div className="algorithm-scroll">
        {GROUPS.map(group=>{
          const list=filtered.filter(a=>a.category===group);
          return list.length>0?<section key={group}><div className="algo-group-label">{group}</div>{list.map(a=><button key={a.id} className={`algo-button ${activeId===a.id?'active':''}`} onClick={()=>choose(a)}>
            <span className="algo-symbol">{SYMBOLS[a.id]}</span><span className="algo-title"><b>{a.name}</b><small>{ABBREV[a.id]}</small></span>{a.status==='ready'?<span className="status-online" title="Çalışır durumda"/>:<LockKeyhole size={12} className="muted-icon"/>}
          </button>)}</section>:null;
        })}
        {!catalog && <div className="sidebar-loading">Katalog yükleniyor...</div>}
        {catalog && filtered.length===0 && <div className="sidebar-loading">Arama sonucu bulunamadı.</div>}
      </div>
      <div className="sidebar-footer"><div className="footer-avatar"><Zap size={16}/></div><div><strong>LAB / Sürüm {APP_VERSION}</strong><small>Karşılaştırma ve analiz</small></div><span className="footer-online"/></div>
    </aside>
    {sidebarOpen && <button className="mobile-scrim" aria-label="Menüyü kapat" onClick={()=>setSidebarOpen(false)}/>}
    <div className="workspace">
      <header className="topbar"><div className="breadcrumb"><button ref={menuButtonRef} className="mobile-menu" aria-controls="lab-sidebar" aria-expanded={sidebarOpen} aria-label="Menüyü aç" onClick={()=>setSidebarOpen(true)}><ListFilter size={19}/></button><span>LABORATUVAR</span><ChevronDown className="breadcrumb-chevron" size={14}/><strong>{tab==='experiments'?'Deney Geçmişi':tab==='compare'?'Karşılaştırma':tab==='benchmark'?'Benchmark':tab==='sensitivity'?'Duyarlılık':tab==='dimensional'?'Yüksek Boyut':tab==='jobs'?'Deney Kuyruğu':tab==='reports'?'Akademik Raporlar':tab==='science'?'Bilimsel Doğrulama':tab==='learn'?'Algoritma Rehberi':'Simülasyon'}</strong></div><div className="topbar-right"><span className="top-pill"><span className="pulse-dot"/> MATEMATİKSEL MOTOR AKTİF</span><span className="build-version">BUILD {APP_VERSION}</span></div></header>
      <main id="main-content" tabIndex={-1} className="content">
        <div className="heading-row"><div><div className="eyebrow"><span className="eyebrow-line"/> ETKİLEŞİMLİ OPTİMİZASYON ARAŞTIRMASI</div><h1>{tab==='compare'?'Algoritma Karşılaştırma Laboratuvarı':tab==='benchmark'?'Çoklu Benchmark Stüdyosu':tab==='sensitivity'?'Parametre Duyarlılığı Laboratuvarı':tab==='dimensional'?'Yüksek Boyutlu Optimizasyon Laboratuvarı':tab==='jobs'?'Kalıcı Deney Görev Kuyruğu':tab==='reports'?'Akademik Deney Raporları':tab==='science'?'Bilimsel Doğrulama ve Performans':tab==='experiments'?'Deney Kayıtları':selectedAlgorithm?.name??'Ateşböceği Algoritması'}</h1><p>{tab==='compare'?'14 algoritmadan seçerek eşit değerlendirme bütçesiyle karşılaştır.':tab==='benchmark'?'Algoritmaları birden fazla amaç fonksiyonunda bağımsız tekrarlarla incele.':tab==='sensitivity'?'Tek bir parametrenin sonuçlara etkisini kontrollü deneylerle ölç.':tab==='dimensional'?'Gerçek 2, 5, 10 ve 30 boyutta optimizasyon davranışını karşılaştır.':tab==='jobs'?'Uzun deneyleri sıraya al, ilerleme ve iptal durumunu takip et.':tab==='reports'?'Kayıtlı deneylerinden tekrarlanabilir yöntem ve sonuç raporları oluştur.':tab==='science'?'Kaydedilmiş D-boyutlu deneyleri matematiksel tutarlılık ve gerçek süre ölçümleriyle incele.':tab==='experiments'?'Bu oturumda gerçekleştirdiğin deneyleri incele ve dışa aktar.':selectedAlgorithm?.description??'Işığa bağlı çekicilik, rassal keşif ve popülasyon dinamiklerini keşfet.'}</p></div><div className="heading-actions"><span className={`release-tag ${ready?'':'upcoming'}`}>{ready?<><span className="pulse-dot"/> ÇALIŞIR MODÜL</>:<><Clock3 size={14}/> GELİŞTİRME SIRASINDA</>}</span></div></div>
        {error && <div className="alert-error" role="alert"><CircleHelp size={18}/><div><strong>Bağlantı / çalıştırma hatası</strong><p>{error} Backend için: <code>uvicorn app.main:app --reload</code></p></div><button onClick={()=>setError(null)} aria-label="Hata mesajını kapat">×</button></div>}
        <ModuleErrorBoundary key={`${tab}:${activeId}`}><Suspense fallback={<ModuleLoading/>}>
        {!ready&&tab!=='experiments'&&tab!=='compare'?<div className="planned-view panel"><span className="planned-glyph">{SYMBOLS[activeId]}</span><span className="eyebrow">ALGORİTMA KÜTÜPHANESİ / {ABBREV[activeId]}</span><h2>{selectedAlgorithm?.name}</h2><p>{selectedAlgorithm?.english}</p><div className="planned-description">{selectedAlgorithm?.description}. Bu algoritma için özgün parametreler, matematiksel motor, ajan görselleştirmesi ve doğrulama testleri sonraki geliştirme aşamasında eklenecek. Burada henüz çalışır bir simülasyon gösterilmiyor.</div><button className="button-primary" onClick={()=>choose(catalog!.algorithms.find(a=>a.id==='fa')!)}><ArrowRight size={17}/> Çalışan FA simülasyonuna geç</button></div>
        :tab==='compare'?<ComparisonLab catalog={catalog}/>
        :tab==='benchmark'?<BenchmarkSuite catalog={catalog}/>
        :tab==='sensitivity'?<SensitivityLab catalog={catalog}/>
        :tab==='dimensional'?<DimensionalLab/>
        :tab==='reports'?<ReportsLab/>
        :tab==='science'?<ScienceLab/>
        :tab==='jobs'?<JobsLab/>
        :tab==='sim'&&activeId==='aco'?<AcoLab/>
        :tab==='experiments'?<section className="panel experiments-panel"><div className="panel-heading"><div><span className="label-overline">ÇALIŞMA OTURUMU</span><h2>Son deneyler</h2></div><span className="meta-inline">{runs.length} deney</span></div><p className="section-intro">En son 6 sonuç bu sekmede tutulur. Sayfa yenilendiğinde oturum geçmişi temizlenir; saklamak için JSON olarak dışa aktar.</p>{runs.length===0?<div className="empty-chart">Henüz deney çalıştırmadın.</div>:<div className="runs-list">{runs.map(r=><div className="run-row" key={r.run_id}><div className="run-glyph"><Activity size={18}/></div><div><strong>{r.objective.toUpperCase()} / {ABBREV[r.algorithm]??r.algorithm.toUpperCase()}</strong><small>Seed {r.seed} · {r.frames.length-1} iterasyon · {r.frames[0].agents.length} ajan</small></div><div className="run-score"><strong>{format(r.frames.at(-1)!.best_so_far)}</strong><small>En iyi değer</small></div><button className="button-subtle" onClick={()=>{setRun(r);setActiveId(r.algorithm);setConfig(prev=>({...prev,...(r.parameters??{}),algorithm:r.algorithm as Config['algorithm']}));setUsedConfig(null);setIndex(0);setPlaying(false);setTab('sim')}}>Görüntüle</button><button className="icon-btn" title="JSON dışa aktar" aria-label="JSON dışa aktar" onClick={()=>downloadJson(r,`${r.run_id}.json`)}><ArrowDownToLine size={18}/></button></div>)}</div>}</section>
        :tab==='learn'&&activeId==='aco'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / ACO</span><h2>Karınca Kolonisi Optimizasyonu</h2></div><BookOpen size={24}/></div><p>ACO, ayrık çizge problemlerinde karıncaların olasılıksal yol kurma davranışını ve ortak feromon bilgisini modeller. Bu laboratuvarda her karınca simetrik Öklidyen TSP için tüm şehirlerden birer kez geçip başladığı şehre dönen bir tur oluşturur.</p><div className="model-grid"><div><span className="label-overline">SONRAKİ ŞEHİR SEÇİMİ</span><div className="formula small-formula">Pᵢⱼ ∝ τᵢⱼ^α (1 / dᵢⱼ)^β</div><p>Yalnızca henüz ziyaret edilmemiş komşular adaydır. Alfa feromonun, beta kısa mesafenin etkisini ayarlar.</p></div><div><span className="label-overline">FEROMON GÜNCELLEMESİ</span><div className="formula small-formula">τᵢⱼ ← (1−ρ)τᵢⱼ + Σₖ(Q / Lₖ)</div><p>Tüm karıncalar turun kullandığı çift yönlü kenarlara feromon bırakır. Buharlaşma her döngü uygulanır.</p></div></div><div className="reference-box"><Info size={18}/><p>Varyant: klasik Ant System (AS), tüm-karınca feromon yatırımı; simetrik TSP, 2-opt içermez. Temel kaynak: Dorigo, Maniezzo &amp; Colorni (1996), The Ant System: Optimization by a Colony of Cooperating Agents. Ayrıntılar <code>docs/ACO_METHODOLOGY.md</code> dosyasında.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> ACO simülasyonuna dön</button></div>
                   :tab==='learn'&&activeId==='de'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / DE</span><h2>Diferansiyel Evrim — DE/rand/1/bin</h2></div><BookOpen size={24}/></div><p>Diferansiyel Evrim, popülasyondaki adaylar arasındaki vektör farklarını kullanarak yeni çözümler üretir. Bu sürüm iki boyutlu, senkron (nesil tabanlı), sürekli minimizasyon için klasik DE/rand/1/bin varyantını uygular. Donörler mevcut hedef bireyden ve birbirinden farklı seçilir.</p><div className="model-grid"><div><span className="label-overline">MUTASYON</span><div className="formula small-formula">Vᵢ = Xᵣ₁ + F · (Xᵣ₂ − Xᵣ₃)</div><p>Üç farklı donör, hedefin dışındaki önceki nesilden seçilir. Mutant arama alanına kırpılır ve her koordinatın öncesi/sonrası kaydedilir.</p></div><div><span className="label-overline">ÇAPRAZLAMA VE SEÇİM</span><div className="formula small-formula">Uᵢⱼ = Vᵢⱼ, randⱼ &lt; CR veya j = jrand</div><div className="formula small-formula">Xᵢ′ = Uᵢ, f(Uᵢ) ≤ f(Xᵢ) ise</div><p>jrand en az bir mutant koordinatı zorunlu kılar. Çaprazlamadan sonraki aday her durumda değerlendirilir; daha kötü aday atılır.</p></div></div><div className="lesson-columns"><div><h3>Nesil sırası</h3><ol><li>Popülasyonu ve başlangıç uygunluklarını değerlendir.</li><li>Her hedef için üç farklı donör seçip mutantı oluştur.</li><li>İki koordinata binom çaprazlama uygula; bir koordinatı zorunlu al.</li><li>Adayı değerlendir, hedefle karşılaştır ve kabul veya reddet.</li><li>Yeni nesil tamamlanınca global en iyi arşivini güncelle.</li></ol></div><div><h3>Denetlenebilir telemetri</h3><ul><li>Hedef bireyin eski koordinatları ve donörlerin kimlikleri/konumları.</li><li>Ham mutant, sınırlandırılmış mutant ve çaprazlama maskesi.</li><li>Değerlendirilen deneme adayı, uygunluk ve kabul/ret sonucu.</li><li>Her neslin kabul, ret, zorunlu çaprazlama sayısı ve gerçek NFE kaydı.</li></ul></div></div><div className="reference-box"><Info size={18}/><p>Kaynak: Storn &amp; Price (1997), <em>Differential Evolution – A Simple and Efficient Heuristic for Global Optimization over Continuous Spaces</em>, Journal of Global Optimization 11, 341–359, DOI: 10.1023/A:1008202821328. Sınır kırpma ve eşit uygunlukta kabul bu eğitim sürümünün açık varyant tercihleridir. Ayrıntılar <code>docs/DE_METHODOLOGY.md</code> dosyasında.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> DE simülasyonuna dön</button></div>
                   :tab==='learn'&&activeId==='gsa'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / GSA</span><h2>Yerçekimsel Arama Algoritması</h2></div><BookOpen size={24}/></div><p>GSA, sayısal optimizasyonda her aday çözümü bir kütle olarak modeller. Amaç fonksiyonu değeri iyi olan adayın çekim kütlesi büyür. Ajanlar, her iterasyonda uygunluğu en iyi Kbest bireyden rastgele ağırlıklı kuvvet alır; güncellenen ivme ve hız yeni konumları oluşturur.</p><div className="model-grid"><div><span className="label-overline">KÜTLE VE YERÇEKİMİ</span><div className="formula small-formula">mᵢ = (worst−fᵢ)/(worst−best); Mᵢ = mᵢ/Σm</div><div className="formula small-formula">G(t)=G₀·exp(−αt/T)</div><p>Bu minimizasyon formülünde en küçük amaç değeri en ağır kütleyi üretir. Tüm değerler eşitse eşit kütle kullanılır. Kbest sayısı N'den 1'e azalır.</p></div><div><span className="label-overline">KUVVET VE HAREKET</span><div className="formula small-formula">Fᵢⱼ = G·MᵢMⱼ·(xⱼ−xᵢ)/(Rᵢⱼ+ε)</div><div className="formula small-formula">aᵢ=Σ(Uⱼ⊙Fᵢⱼ)/Mᵢ; v′=Uᵢ⊙v+aᵢ; x′=x+v′</div><p>Her çekim, önceki neslin donmuş konum ve kütlelerine göre hesaplanır. Rastgele katsayılar bağımsız koordinatlara uygulanır; sonuçlar arama sınırlarına kırpılır.</p></div></div><div className="lesson-columns"><div><h3>Hesaplama sırası</h3><ol><li>Popülasyonu üret, amaç değerlerini ve normalize kütleleri hesapla.</li><li>G(t) katsayısını ve çekime katılan Kbest kümesini güncelle.</li><li>Her ajan için rastgele ağırlıklı kuvvet toplamını hesapla.</li><li>İvme, hız ve yeni konumu hesaplayıp sınırları uygula.</li><li>N konumu tekrar değerlendir, kütleleri ve en iyi arşivi güncelle.</li></ol></div><div><h3>Gözlemlenebilir hesaplar</h3><ul><li>Güncel normalize kütle ve kuvvet hesabında kullanılan eski kütle.</li><li>Kuvvet, ivme, hız ve eski konum.</li><li>Seçilen ajan üzerindeki en büyük tek çekim katkısının kaynağı.</li><li>G(t), Kbest ve toplam NFE kayıtları.</li></ul></div></div><div className="reference-box"><Info size={18}/><p>Kaynak: Rashedi, Nezamabadi-pour ve Saryazdi (2009), <em>GSA: A Gravitational Search Algorithm</em>, Information Sciences 179, 2232–2248, DOI: 10.1016/j.ins.2009.03.004. Kullanılan sınır kırpma ve hız sıfırlama tercihi dahil uygulama varyantı <code>docs/GSA_METHODOLOGY.md</code> dosyasında açıklanır.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> GSA simülasyonuna dön</button></div>
          :tab==='learn'&&activeId==='sa'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / SA</span><h2>Tavlama Benzetimi (Simulated Annealing)</h2></div><BookOpen size={24}/></div><p>SA sürü optimizasyonu değil, tek bir mevcut çözüme komşu adaylar öneren stokastik bir arama yöntemidir. Daha iyi adaylar daima kabul edilir; daha kötü adaylar ise sıcaklığa bağlı olasılıkla kabul edilerek yerel minimumlardan kaçma fırsatı verir. En iyi tarihsel çözüm ayrı tutulur.</p><div className="model-grid"><div><span className="label-overline">METROPOLIS KABUL KRİTERİ</span><div className="formula small-formula">P(kabul) = 1 [Δf ≤ 0], exp(−Δf/T) [Δf &gt; 0]</div><p>Δf = f(aday) − f(mevcut). U(0,1) rastgele çekilişi P'den küçükse aday kabul edilir. Her teklif, reddedilse de bir değerlendirme sayılır.</p></div><div><span className="label-overline">GEOMETRİK SOĞUMA</span><div className="formula small-formula">T(t) = T₀ · r^(t−1)</div><p>t = 1, 2, ... T. Her adımda yeni komşu, mevcut noktanın etrafına N(0,σ²) adımı eklenerek oluşturulur; σ aralık genişliğinin seçilen oranıdır.</p></div></div><div className="lesson-columns"><div><h3>Her iterasyon</h3><ol><li>Mevcut çözümün çevresinde bir aday üret.</li><li>Arama sınırına kırp ve uygunluğu değerlendir.</li><li>Δf ve sıcaklıktan kabul olasılığını hesapla.</li><li>Rastgele sayı ile kabul/ret kararını ver.</li><li>Kabul edilirse güncel konumu güncelle; en iyi kayıt daha iyiyse arşivle.</li></ol></div><div><h3>Deneyin ölçümleri</h3><ul><li>Geçerli sıcaklık ve aday uygunluğu</li><li>Kötü aday kabulü ve toplam ret sayısı</li><li>Reddedilen adayın ayrı işaretlenmesi</li><li>Her adım için sabit rastgele tohum ve NFE = T + 1</li><li>Tek çözüm: popülasyon çeşitliliği SA için anlamlı değildir</li></ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Kaynak:</strong> Kirkpatrick, Gelatt ve Vecchi (1983), <em>Optimization by Simulated Annealing</em>, Science 220(4598), 671–680. Uygulama: sabit Gaussian komşu ölçeği, geometrik soğuma ve sınır kırpmalı 2B Metropolis yaklaşımı. Ayrıntılar <code>docs/SA_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> SA simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='iwo'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / IWO</span><h2>İstilacı Yabani Ot Optimizasyonu</h2></div><BookOpen size={24}/></div><p>IWO (Invasive Weed Optimization), bitkilerin yerleşmesini, uygunluğa bağlı tohum üretimini, tohumların normal dağılımla saçılmasını ve sınırlı kaynaklar için rekabeti modeller. Diğer çoğu modülden farklı olarak popülasyon sabit değildir.</p><div className="model-grid"><div><span className="label-overline">UYGUNLUĞA BAĞLI TOHUM</span><div className="formula small-formula">Sᵢ = ⌊Smin + (fmax−fᵢ)/(fmax−fmin)·(Smax−Smin)⌋</div><p>Düşük amaç değeri daha çok tohum üretir. Tüm uygunluklar aynıysa bölme yerine en yüksek tohum kapasitesi kullanılır.</p></div><div><span className="label-overline">AZALAN YAYILMA</span><div className="formula small-formula">σ(t) = σson + (σilk−σson)·((T−t)/T)ᵐ</div><p>Her tohum ebeveyn konumuna eklenen bağımsız Gaussian adımla oluşur; koordinatlar problem sınırına kırpılır.</p></div></div><div className="lesson-columns"><div><h3>Algoritma döngüsü</h3><ol><li>Başlangıç popülasyonunu örnekle ve değerlendir.</li><li>Her bitkiye uygunluğuna göre tohum sayısı ata.</li><li>Tohumları ebeveyn etrafına Gaussian dağıt.</li><li>Tüm yeni adayları birer kez değerlendir.</li><li>Ebeveyn + filizleri birleştir; en iyi üst sınır kadar bireyi yaşat.</li><li>En iyi çözümü arşivle ve yeni σ değeriyle devam et.</li></ol></div><div><h3>Gerçek deney kayıtları</h3><ul><li>Her bireyin değişmeyen kimliği.</li><li>Hayatta kalan filizin ebeveyn konumu ve ham Gaussian sıçraması.</li><li>Üretilen, seçilen ve elenen tohum sayısı.</li><li>O anki popülasyon ve sigma.</li><li>Çıkarılan tohumlar dahil gerçek NFE.</li></ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Kaynak:</strong> Mehrabian &amp; Lucas (2006), <em>A novel numerical optimization algorithm inspired from weed colonization</em>, Ecological Informatics 1(4), 355–366. DOI: 10.1016/j.ecoinf.2006.07.003. Varyant ayrıntıları <code>docs/IWO_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> IWO simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='sma'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / SMA</span><h2>Cıvık Mantar Algoritması (Slime Mould Algorithm)</h2></div><BookOpen size={24}/></div><p>SMA, cıvık mantarın besine yönelirken gösterdiği titreşim ve geri bildirim davranışını matematiksel olarak modeller. Bu sürüm, 2 boyutlu sürekli minimizasyonda uyarlamalı ağırlıklar ve üç ayrı konum güncelleme türü kullanır. Her iterasyon önceki popülasyondan eşzamanlı hesaplanır ve en iyi çözüm ayrıca arşivlenir.</p><div className="model-grid"><div><span className="label-overline">BESİNE YAKLAŞMA</span><div className="formula small-formula">X′ = Xbest + vb · (W · XA − XB)</div><p>p = tanh(|fᵢ − fbest|) olasılığına göre seçilir. W, önceki neslin sıralı uygunluklarına göre pozitif veya negatif geri bildirim üretir.</p></div><div><span className="label-overline">BÜZÜLME / BAĞIMSIZ KEŞİF</span><div className="formula small-formula">X′ = vc · X; &nbsp; P(yeniden başlat)=z</div><p>vb ∈ [−a,a], vc ∈ [−b,b], a=atanh(1−t/T) ve b=1−t/T. Olasılık z olan yeniden başlangıçlar arama alanından yeni konum örnekler.</p></div></div><div className="lesson-columns"><div><h3>Simülasyon adımları</h3><ol><li>Popülasyonu oluştur ve amaç fonksiyonunu değerlendir.</li><li>Uyarlanır W ağırlıklarını sıralamaya göre belirle.</li><li>Arşivdeki en iyi çözüm ve p olasılıklarını hesapla.</li><li>Yeniden başlangıç, yaklaşma veya büzülme seç.</li><li>Sınırları uygula, tam N yeni fonksiyon değerlendirmesi yap.</li></ol></div><div><h3>Denetlenebilir değişkenler</h3><ul><li>Bireysel ağırlık W ve yaklaşma olasılığı p.</li><li>Gerçek kaynak XA, XB ve eski/arşiv konumu.</li><li>vb/vc vektörleri ve örneklenen rastgele kararlar.</li><li>Yaklaşma, büzülme, yeniden başlangıç sayıları ve gerçek NFE.</li></ul></div></div><div className="reference-box"><Info size={18}/><p>Temel kaynak: Li ve ark. (2020), <em>Slime mould algorithm: A new method for stochastic optimization</em>, FGCS 111, 300–323, DOI: 10.1016/j.future.2020.03.055. <strong>Not:</strong> Standart büzülme kuralı orijine doğru güçlü bir eğilim oluşturabilir; özellikle minimumu orijinde olan fonksiyonlarda başarımı bu bağlamda değerlendir. Denklemler ve uygulama tercihleri <code>docs/SMA_METHODOLOGY.md</code> içinde.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> SMA simülasyonuna dön</button></div>
         :tab==='learn'&&activeId==='ssa'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / SSA</span><h2>Salp Sürüsü Algoritması (Salp Swarm Algorithm)</h2></div><BookOpen size={24}/></div><p>Salplerin zincir halinde hareketinden esinlenen SSA'da ilk birey liderdir, kalan N−1 birey takipçidir. Lider, en iyi bulunan besin konumu etrafında arama yapar; takipçiler sırayla önceki bireyin güncellenmiş konumuna göre ilerler. Besin konumu her adım boyunca sabitlenmiş tarihsel en iyi çözümdür.</p><div className="model-grid"><div><span className="label-overline">LİDERİN ARAMA DENKLEMİ</span><div className="formula small-formula">x₁ⱼ′ = Fⱼ ± c₁[(ubⱼ−lbⱼ)c₂ⱼ + lbⱼ]</div><p>Her eksende c₂, c₃ ∈ [0,1]. İşaret c₃ ≥ 0,5 olduğunda +, aksi durumda − olur. c₁(t)=c₁₀ exp(−(4t/T)²), varsayılan c₁₀=2.</p></div><div><span className="label-overline">TAKİPÇİLERİN ZİNCİRİ</span><div className="formula small-formula">xᵢ′ = ½ (xᵢ eski + xᵢ₋₁ yeni)</div><p>Takipçiler 2'den N'ye sırayla hesaplanır; bu varyantta bir önceki salpın <strong>aynı jenerasyondaki güncel</strong> konumu kullanılır. Her eksen arama sınırlarında tutulur.</p></div></div><div className="lesson-columns"><div><h3>Simülasyon adımları</h3><ol><li>N salpi rastgele oluştur, uygunluklarını değerlendir.</li><li>En iyi besin kaynağını her jenerasyon başında sabitle.</li><li>c₁ katsayısını ve liderin c₂/c₃ örneklerini hesapla.</li><li>Lideri güncelle ve takipçi zincirini önden arkaya sırayla hareket ettir.</li><li>N yeni uygunluk değeri hesapla ve en iyi çözümü arşivle.</li></ol></div><div><h3>Denetlenebilir bilgiler</h3><ul><li>Seçilen liderin c₂ ve c₃ koordinat katsayıları.</li><li>Her takipçinin eski konumu ve yeni öncül konumu.</li><li>Besin hedefi, c₁ kontrol değeri ve zincir uzunluğu.</li><li>91 kare (90 iterasyonda) ve NFE=N(T+1).</li></ul></div></div><div className="reference-box"><Info size={18}/><p>Akademik temel: Mirjalili ve çalışma arkadaşları (2017), <em>Salp Swarm Algorithm: A bio-inspired optimizer for engineering design problems</em>, Advances in Engineering Software 114, 163–191, DOI: 10.1016/j.advengsoft.2017.07.002. Varyant ayrıntıları <code>docs/SSA_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> SSA simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='cs'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / CS</span><h2>Guguk Kuşu Arama (Cuckoo Search)</h2></div><BookOpen size={24}/></div><p>CS, parazit kuluçka davranışından esinlenen sürekli optimizasyon yöntemidir. Her yuva bir aday çözümü temsil eder. Bir Lévy uçuşuyla oluşan aday yumurta, rastgele bir ev sahibi yuvaya bırakılır; daha iyi ise o yuvayı değiştirir. Her jenerasyonda en kötü yuvaların belirlenen kısmı yeniden kurulur.</p><div className="model-grid"><div><span className="label-overline">LÉVY UÇUŞU · MANTEGNA</span><div className="formula small-formula">L = u / |v|^(1/β)</div><p>u ve v, β ile ölçeklenen normal dağılımlardan örneklenir; ağır kuyruklu adımlar nadiren büyük sıçramalar oluşturur. Kodda ölçeklenen yön, (yuva − arşiv en iyisi) ile küçük rassal terimin toplamıdır.</p></div><div><span className="label-overline">YUVA TERK ETME</span><div className="formula small-formula">k = round(pₐ × N)</div><p>Her tur en kötü k yuva, en iyi mevcut yuva korunarak rastgele yeniden başlatılır. NFE = N + T × (N + k).</p></div></div><div className="reference-box"><Info size={18}/><p>Bu uygulama, Yang &amp; Deb (2009) yaklaşımının açıkça belgelenmiş, <strong>rastgele ev sahibi + en kötü k yuvayı yenileme</strong> varyantıdır; tüm uygulamalarla birebir aynı değildir. Akademik kaynak: X.-S. Yang ve S. Deb, <em>Cuckoo Search via Lévy Flights</em>, NaBIC 2009, DOI: 10.1109/NABIC.2009.5393690. Ayrıntılar <code>docs/CS_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> CS simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='mfo'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / MFO</span><h2>Güve-Alev Optimizasyonu</h2></div><BookOpen size={24}/></div><p>MFO, geceleri ışık kaynaklarının çevresinde oluşan spiral güve hareketinden esinlenen bir sürekli optimizasyon yöntemidir. Güveler güncel aday çözümleri, alevler ise şimdiye kadar bulunan iyi konumların sıralı belleğini temsil eder.</p><div className="model-grid"><div><span className="label-overline">LOGARİTMİK SPİRAL</span><div className="formula small-formula">M′ = F + |F−M| · e^(bt) · cos(2πt)</div><p>Her koordinat için bağımsız t örneklenir. F alev konumudur; b spiral şekil katsayısıdır. Alev etrafında yapılan hareket ayrık iterasyon konumları olarak gösterilir.</p></div><div><span className="label-overline">AZALAN ALEV SAYISI</span><div className="formula small-formula">Fₙ = round(N − l(N−1)/T)</div><p>İterasyon ilerledikçe kullanılan alev sayısı N'den 1'e iner. Her güve uygunluk sırasına göre bir aleve atanır; fazladan güveler son aktif alevi izler.</p></div></div><div className="lesson-columns"><div><h3>Hesaplama adımları</h3><ol><li>N güveyi rastgele oluştur ve değerlendir.</li><li>En iyi N farklı konumdan sıralı alev belleğini oluştur.</li><li>Güveleri mevcut uygunluklarına göre sırala.</li><li>Azalan alev sayısıyla her güveyi bir aleve eşleştir.</li><li>Spiral konumunu hesapla, sınırları uygula ve değerlendir.</li><li>Alev belleğini ve tüm kare kayıtlarını güncelle.</li></ol></div><div><h3>Bilimsel notlar</h3><ul><li>t, [-1−l/T, 1] aralığından örneklenir.</li><li>Arşivde aynı koordinatın tekrarını tutmayan açıkça belgelenmiş bir varyant kullanılır.</li><li>Her jenerasyonda tam N gerçek amaç fonksiyonu değerlendirmesi vardır.</li><li>Grafiklerde çizilen güve–alev bağlantıları hesaplanan hedeflerdir; sürekli fiziksel uçuş yörüngesi iddiası değildir.</li></ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Akademik kaynak:</strong> Seyedali Mirjalili, <em>Moth-Flame Optimization Algorithm: A Novel Nature-inspired Heuristic Paradigm</em>, Knowledge-Based Systems 89 (2015), 228–249, DOI: 10.1016/j.knosys.2015.07.006. Varyant ayrıntıları: <code>docs/MFO_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> MFO simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='woa'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / WOA</span><h2>Balina Optimizasyon Algoritması</h2></div><BookOpen size={24}/></div><p>WOA, kambur balinaların baloncuk ağı avlanma davranışından esinlenir. Her nesilde bir balina ya küresel en iyi çözümün çevresini daraltarak arar, ya rastgele seçilmiş başka balinaya yönelerek yeni alanları keşfeder ya da en iyi çözüm etrafında spiral bir aday oluşturur.</p><div className="model-grid"><div><span className="label-overline">KUŞATMA VE KEŞİF</span><div className="formula small-formula">X′ = Xₜ − A ⊙ |C ⊙ Xₜ − X|</div><p>A = 2ar₁ − a, C = 2r₂. max(|A|) ≥ 1 olduğunda Xₜ önceki nesilden rastgele farklı bir balina, aksi halde dondurulmuş tarihsel en iyi konumdur.</p></div><div><span className="label-overline">BALONCUK-AĞI SPİRALİ</span><div className="formula small-formula">X′ = X* + |X*−X| · e^(bℓ) · cos(2πℓ)</div><p>ℓ ∈ [−1,1]. Varsayılan spiral olasılığı 0,5; kalan olasılıkta kuşatma/keşif seçilir. Her aday arama sınırlarına kırpılır.</p></div></div><div className="lesson-columns"><div><h3>Simülasyonun adımları</h3><ol><li>N balinayı üret ve değerlendir.</li><li>En iyi çözüm arşivini o adım için dondur.</li><li>Her balina için p olasılığını üret.</li><li>Spiral veya A/C katsayılarına göre kuşatma/keşif adayını hesapla.</li><li>Yeni N konumu değerlendir ve en iyi arşivini güncelle.</li><li>Dal türü, önceki nokta, hedef ve katsayıları karede kaydet.</li></ol></div><div><h3>Denetlenebilir veriler</h3><ul><li>Arama, kuşatma ve spiral hareketlerinin gerçek sayıları.</li><li>Her balina için p, A, C veya ℓ katsayıları.</li><li>Önceki nesilden sabitlenmiş hedef konumu.</li><li>Azalan a, sabit tohum ve NFE = N × (T+1).</li><li>Vektör A'da keşif için en büyük mutlak bileşen sınırı kullanılır; ayrıntısı belgelenmiştir.</li></ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Kaynak:</strong> Mirjalili &amp; Lewis (2016), <em>The Whale Optimization Algorithm</em>, Advances in Engineering Software 95, 51–67, DOI: 10.1016/j.advengsoft.2016.01.008. Hareket dallanması ve kullanılan varyant: <code>docs/WOA_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> WOA simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='gwo'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / GWO</span><h2>Gri Kurt Optimizasyonu (Grey Wolf Optimizer)</h2></div><BookOpen size={24}/></div><p>GWO, gri kurt sürüsünün avı kuşatma stratejisinden esinlenen bir sürekli optimizasyon modelidir. Her nesilde güncel en iyi üç farklı kurt alfa (α), beta (β) ve delta (δ) olur; diğerleri omega (ω) grubuna girer. Kurtların hareketi üç lider için ayrı hesaplanan adayların ortalamasından oluşur.</p><div className="model-grid"><div><span className="label-overline">KUŞATMA KATSAYILARI</span><div className="formula small-formula">Aₖ = 2a·r₁ₖ − a ; Cₖ = 2r₂ₖ</div><p>a katsayısı başlangıçta 2'dir ve süreç boyunca 0'a azalır; r₁ ve r₂ her kurt, lider ve koordinat için ayrı üretilir.</p></div><div><span className="label-overline">ÜÇ LİDERDEN KONUM</span><div className="formula small-formula">Xₖ = Lₖ − Aₖ|CₖLₖ − X| ; X′ = (X₁+X₂+X₃)/3</div><p>Liderler, hareket öncesindeki güncel alfa/beta/delta konumlarıdır. Adaylar ortalanır, sınırlar uygulanır ve yeni uygunluk hesaplanır.</p></div></div><div className="lesson-columns"><div><h3>Simülasyonun adımları</h3><ol><li>N kurt konumunu başlat, uygunluklarını ölç.</li><li>Alfa, beta ve delta kurtlarını sırala.</li><li>Her kurt için üç liderden bağımsız aday konum hesapla.</li><li>Üç adayın ortalamasını al, sınırları uygula.</li><li>Yeni popülasyonu değerlendir ve liderleri güncelle.</li><li>En iyi tarihsel çözümü ayrı arşivde tut.</li></ol></div><div><h3>İnceleyebileceğin veriler</h3><ul><li>Güncel alfa, beta, delta ve omega rolleri.</li><li>Gerçek harekette kullanılan üç lider hedefi.</li><li>Üç ara aday konum (X₁, X₂, X₃) ve a değeri.</li><li>İterasyon bazlı NFE ve yakınsama.</li><li>Sabit tohumla tekrarlanabilirlik.</li></ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Akademik kaynak:</strong> Mirjalili, Mirjalili &amp; Lewis (2014), <em>Grey Wolf Optimizer</em>, Advances in Engineering Software 69, 46–61, DOI: 10.1016/j.advengsoft.2013.12.007. Varsayılan a₀=2 temel denklemlerle uyumludur; a₀ değiştirildiğinde açıkça belirtilen parametre varyantı uygulanır. Ayrıntılar <code>docs/GWO_METHODOLOGY.md</code>.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> GWO simülasyonuna dön</button></div>
        :tab==='learn'&&activeId==='ba'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / BA</span><h2>Yarasa Algoritması (Bat Algorithm)</h2></div><BookOpen size={24}/></div><p>BA, yarasaların ekolokasyon davranışından esinlenen bir sürekli optimizasyon yöntemidir. Frekans örneklemesi hız güncellemesini belirler; ses şiddeti (A) daha iyi adayın kabul edilme ihtimalini, darbe oranı (r) ise yerel aramanın sıklığını kontrol eder. Bu sürüm 2B, eşzamanlı ve tek aday / yarasa / iterasyon varyantını uygular.</p><div className="model-grid"><div><span className="label-overline">FREKANS VE HIZ</span><div className="formula small-formula">fᵢ = fₘᵢₙ + (fₘₐₓ − fₘᵢₙ) U(0,1)</div><div className="formula small-formula">vᵢ ← vᵢ + (xᵢ − x*) fᵢ</div><p>Küresel en iyi konum her adım boyunca sabitlenir. Global aday xᵢ + vᵢ ile hesaplanır.</p></div><div><span className="label-overline">YEREL ARAMA VE KABUL</span><div className="formula small-formula">x' = x* + ε · mean(A), ε ∼ U(−1,1)</div><div className="formula small-formula">A ← αA ; r ← r₀ (1 − e<sup>−γt</sup>)</div><p>U(0,1) &gt; r olduğunda yerel aday denenir. Aday daha iyi ve bağımsız kabul örneği A değerinden küçükse kabul edilir; yalnızca bu durumda A ve r güncellenir.</p></div></div><div className="reference-box"><Info size={18}/><p>Kaynak: Xin-She Yang, <em>A New Metaheuristic Bat-Inspired Algorithm</em> (2010), DOI: 10.1007/978-3-642-12538-6_6. Bu eğitim varyantında güncel darbe oranı başlangıçta sıfırdır ve kabul edilen adımlar sonrasında r₀'a yaklaşır. Reddedilen adaylar da değerlendirildiği için NFE = N × (T + 1). Tam ayrıntılar <code>docs/BA_METHODOLOGY.md</code> dosyasında.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> BA simülasyonuna dön</button></div>
       :tab==='learn'?<div className="learn-view"><section className="panel overview-panel"><div className="panel-heading"><div><span className="label-overline">ARAŞTIRMA DOSYASI / {isPso?'PSO':isAbc?'ABC':'FA'}</span><h2>{isPso?'Parçacık Sürü Optimizasyonu nasıl çalışır?':isAbc?'Yapay Arı Kolonisi nasıl çalışır?':'Ateşböceği Algoritması nasıl çalışır?'}</h2></div><BookOpen size={24}/></div><p>{isPso?"PSO, parçacıkların hem geçmişte buldukları kişisel en iyi konumları (pBest), hem de sürünün bugüne kadar bulduğu küresel en iyi konumu (gBest) kullanarak hızlarını güncellediği, sürekli optimizasyon yöntemidir.":isAbc?"ABC, besin kaynaklarını kullanan işçi arılar, kaliteli kaynaklara yönelen gözlemci arılar ve tıkanan kaynakları yenileyen keşifçilerden oluşur. Ekrandaki ajanlar besin kaynaklarıdır; arıların kendisi değildir. Bir döngü, işçi ve gözlemci aşamalarının ardından keşifçi kontrolü içerir.":"Firefly Algorithm, meta-sezgisel optimizasyon yöntemidir. Amaç fonksiyonu değeri daha iyi olan ajanlar daha parlak kabul edilir; diğerleri onlara doğru mesafeye bağlı bir çekimle ilerler. Rassal adımlar keşfi sağlar. Bu sürüm iki değişkenli sürekli minimizasyon problemleri için hazırlanmıştır."}</p><ModelExplanation algorithm={isPso?'pso':isAbc?'abc':'fa'}/><div className="lesson-columns"><div><h3>Simülasyondaki adımlar</h3><ol>{isAbc?<><li>Besin kaynaklarını başlangıçta rastgele üret.</li><li>İşçi arı: her kaynağı komşu karşılaştırmasıyla bir kez iyileştirmeyi dene.</li><li>Gözlemci arı: kaynak kalitesiyle orantılı olasılıkla seçim yap ve adayları değerlendir.</li><li>Limit aşılırsa tek kaynağı keşifçiyle yeniden başlat.</li><li>Gerçek fonksiyon değerlendirme sayısını, kaynak rolleri ve arşivi kaydet.</li></>:isPso?<><li>Başlangıç pozisyonlarını üret ve hızları sıfırla.</li><li>Kişisel ve küresel en iyi kayıtları oluştur.</li><li>Atalet, bilişsel ve sosyal terimlerle hızları güncelle.</li><li>Hızları kısıtla, pozisyonları güncelle ve sınırları uygula.</li><li>Kişisel ve küresel en iyi çözümleri güncelle.</li><li>İterasyon izlerini, vektörleri ve istatistikleri kaydet.</li></>:<><li>Başlangıç popülasyonunu, rastgele tohum ile üret.</li><li>Her ateşböceğinin amaç fonksiyonu değerini hesapla.</li><li>Daha parlak diğer ateşböceklerine çekim hareketini uygula.</li><li>Rassal terim ekle, konumu sınırlar içinde tut.</li><li>Yeni uygunlukları ve arşivdeki en iyi çözümü güncelle.</li><li>İterasyon izlerini ve istatistikleri kaydet.</li></>}</ol></div><div><h3>Bilimsel notlar</h3><ul>{isAbc?<><li>Popülasyon büyüklüğü görüntülenen besin kaynağı sayısını ifade eder.</li><li>Her döngüde N işçi ve N gözlemci değerlendirmesi, gerektiğinde 1 keşifçi değerlendirmesi yapılır.</li><li>Gözlemci seçimleri, uygunluğun pozitif nektar dönüşümüne göre roulette yöntemiyle yapılır.</li><li>Keşifçiler yüzünden ABC değerlendirme bütçesi FA/PSO ile aynı değildir; henüz ortak kıyaslamaya dahil edilmedi.</li></>:isPso?<><li>pBest her parçacığın kişisel en iyi arşividir, gBest tüm sürünün arşividir.</li><li>Her eksen ve parçacık için bağımsız rassal katsayılar kullanılır.</li><li>Hız ve konum sınırları modele ait açık kontrol tercihleridir.</li><li>Aynı rastgele tohum ve parametreler tam olarak tekrarlanır.</li></>:<><li>Minimizasyonda düşük amaç fonksiyonu değeri daha iyi parlaklığa karşılık gelir.</li><li>Bu uygulama, başlangıç neslinin parlaklığını sabit tutan ardışık çekim varyantını kullanır.</li><li>Arşivlenmiş en iyi değer monoton iyileşir; anlık en iyi değer dalgalanabilir.</li><li>Gösterilen hedef çizgisi, seçilen ajanın o nesildeki en güçlü çekim hedefini temsil eder.</li></>}</ul></div></div><div className="reference-box"><Info size={18}/><p><strong>Akademik kaynak:</strong> {isAbc?"Derviş Karaboğa, An Idea Based on Honey Bee Swarm for Numerical Optimization (2005).":isPso?"Kennedy & Eberhart, Particle Swarm Optimization (1995).":"Xin-She Yang, Firefly Algorithms for Multimodal Optimization (2009)."} Uygulama varyantının ayrıntıları <code>docs/METHODOLOGY.md</code> dosyasında açıklanır.</p></div></section><button className="button-primary" onClick={()=>setTab('sim')}><Play size={17}/> Simülasyona dön</button></div>
        :<>
          <div className="stats-grid">
            <div className="stat-card"><div className="stat-icon teal"><Target size={19}/></div><span>EN İYİ AMAÇ DEĞERİ</span><strong>{frame?format(frame.best_so_far,6):'—'}</strong><small><span className="stat-sparkle">↘</span> Kaydedilmiş en iyi sonuç</small></div>
            <div className="stat-card"><div className="stat-icon orange"><Sparkles size={19}/></div><span>{isPso?'AKTİF PARÇACIK':isAbc?'BESİN KAYNAĞI':isCs?'AKTİF YUVA':isMfo?'AKTİF GÜVE':isGwo?'AKTİF KURT':isWoa?'AKTİF BALİNA':isBa?'AKTİF YARASA':isSsa?'AKTİF SALP':isSma?'AKTİF CİVIK MANTAR':isIwo?'CANLI YABANİ OT':isSa?'MEVCUT ÇÖZÜM':isGsa?'AKTİF KÜTLE':isDe?'AKTİF BİREY':'AKTİF ATEŞBÖCEĞİ'}</span><strong>{frame?.agents.length??(isSa?1:config.population_size)}<span className="stat-unit"> {isSa?'nokta':'ajan'}</span></strong><small>{isSa?'Her adımda bir komşu aday':'İki boyutlu arama popülasyonu'}</small></div>
            <div className="stat-card"><div className="stat-icon blue"><Gauge size={19}/></div><span>FONKSİYON DEĞERLENDİRME</span><strong>{frame?.function_evaluations.toLocaleString('tr-TR')??'—'}</strong><small>{currentRun?`${currentRun.frames.at(-1)!.function_evaluations.toLocaleString('tr-TR')} toplam gerçek değerlendirme`:'Başlatıldığında hesaplanacak'}</small></div>
            <div className="stat-card"><div className="stat-icon purple"><GitBranch size={19}/></div><span>{isSa?'KABUL ORANI':'POPÜLASYON ÇEŞİTLİLİĞİ'}</span><strong>{frame?(isSa?`%${(100*(frame.sa_accepted_total??0)/Math.max(1,frame.iteration)).toFixed(1)}`:format(frame.diversity,3)):'—'}</strong><small>{isSa?'Kabul edilen adayların payı':'Merkeze ortalama Öklid uzaklığı'}</small></div>
          </div>
          <div className="lab-grid">
            <div className="lab-left">
              <section className="panel visualization-panel"><div className="panel-heading"><div><span className="label-overline">01 / DAVRANIŞ GÖRSELLEŞTİRME</span><h2>Canlı simülasyon <span className="surface-pill">2D Surface</span></h2></div><div className="visual-options"><label><input type="checkbox" checked={trails} onChange={e=>setTrails(e.target.checked)}/> İzler</label><label><input type="checkbox" checked={showTargets} onChange={e=>setShowTargets(e.target.checked)}/> {isPso?'Hız vektörleri':isAbc?'Komşu referansı':isCs?'Uçuş ve terk izleri':isMfo?'Alevler / eşleşmeler':isGwo?'Üç lider / hedefler':isWoa?'Kuşatma / spiral hedefleri':isSsa?'Zincir / besin hedefi':isSma?'Besin / referanslar':isIwo?'Tohum / ebeveyn bağları':isSa?'Komşu aday / karar':isGsa?'Çekim kuvvetleri':'Çekim'}</label></div></div>
                <Landscape run={currentRun} frame={frame} objective={currentRun?.objective??config.objective} selectedId={selectedId} setSelectedId={setSelectedId} trails={trails} showTargets={showTargets}/>
                <div className="playback"><div className="transport-controls"><button className="icon-btn" title="Başa al" aria-label="Başa al" disabled={!run} onClick={()=>{setIndex(0);setPlaying(false)}}><SkipBack size={18}/></button><button className="icon-btn" title="Önceki iterasyon" aria-label="Önceki iterasyon" disabled={!run} onClick={()=>{setIndex(i=>Math.max(0,i-1));setPlaying(false)}}><SkipBack size={14}/></button><button className="play-btn" disabled={!run} aria-label={playing?'Duraklat':'Oynat'} onClick={()=>{if(index===run!.frames.length-1)setIndex(0);setPlaying(!playing)}}>{playing?<Pause fill="currentColor" size={18}/>:<Play fill="currentColor" size={18}/>}</button><button className="icon-btn" title="Sonraki iterasyon" aria-label="Sonraki iterasyon" disabled={!run} onClick={()=>{setIndex(i=>Math.min(run!.frames.length-1,i+1));setPlaying(false)}}><SkipForward size={14}/></button><button className="icon-btn" title="Sona git" aria-label="Sona git" disabled={!run} onClick={()=>{setIndex(run!.frames.length-1);setPlaying(false)}}><FastForward size={18}/></button></div><div className="scrub-area"><div className="scrub-info"><span>İTERASYON <strong>{frame?.iteration??0}</strong> / {run?.frames.length?run.frames.length-1:config.iterations}</span><span>{run?`${Math.round(index/Math.max(1,run.frames.length-1)*100)}%`:'—'}</span></div><input type="range" aria-label="İterasyon zaman çizelgesi" min="0" max={run?run.frames.length-1:1} value={index} disabled={!run} onChange={e=>{setIndex(Number(e.target.value));setPlaying(false)}}/></div><select className="speed-select" aria-label="Oynatma hızı" value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={.5}>0.5×</option><option value={1}>1×</option><option value={2}>2×</option><option value={4}>4×</option></select></div>
                <div className="visual-hint"><Info size={14}/> {isPso?'Parçacığı seçerek hızını, kişisel ve küresel en iyi konumlarını incele.':isAbc?'Besin kaynağını seçerek son işlemi (işçi / gözlemci / keşifçi), deneme sayacını ve seçim olasılığını incele.':isCs?'Bir yuvayı seçerek kabul edilen Lévy uçuşlarını, terk edilen yuvaları ve önerilen sıçramayı incele.':isMfo?'Güveyi seçerek izlediği alev konumunu, alev sırasını ve gerçek spiral t değerlerini incele.':isGwo?'Kurda tıklayarak rolünü, hareketin üç liderini ve üç ayrı aday konumunu incele.':isWoa?'Balinayı seçerek keşif, kuşatma veya spiral hareketi ile gerçek katsayılarını incele.':isBa?'Yarasaya tıklayarak aday konumunu, frekansını ve kabul durumunu incele.':isSsa?'Lider veya takipçiyi seçerek zincir bağlarını, besin hedefini ve gerçek konum güncellemesini incele.':isSma?'Birey seçip uyarlamalı W ağırlığını, yaklaşma olasılığını ve XA/XB referanslarını incele.':isIwo?'Yeni yetişen tohumu seçerek ebeveynini, gerçek saçılım adımını ve rekabet sonuçlarını incele.':isSa?'Mevcut çözümü seçerek komşu adayı, Δf, sıcaklığı ve Metropolis kabul kararını incele.':isGsa?'Bir kütleyi seçerek kullanılan kuvveti, önceki konumu, ivmeyi ve baskın çekim kaynağını incele.':isDe?'Bir bireyi seçerek üç donörü, mutant ve deneme vektörünü, çaprazlama maskesini ve seçim kararını incele.':'Ajanın üzerine tıklayarak konum, parlaklık ve en güçlü çekim hedefini incele.'}</div>
              </section>
              {isDe && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / EVRİM DİNAMİĞİ</span><h2>Mutasyon, çaprazlama ve açgözlü seçim</h2></div><span className="surface-pill">DE/rand/1/bin</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Kabul edilen aday<strong>{frame.de_accepted_count??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Reddedilen aday<strong>{frame.de_rejected_count??0}</strong></div><div><span className="abc-phase-dot scout"/> Zorunlu çaprazlama<strong>{frame.de_forced_crossover_count??0}</strong></div></div><p className="abc-phase-caption">F = <strong>{config.de_mutation_factor.toFixed(2)}</strong> · CR = <strong>{config.de_crossover_rate.toFixed(2)}</strong> · Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong>. Her hedef için üç ayrı donör, mutant ve deneme vektörü kaydedilir. Reddedilen denemeler de değerlendirmeye dahildir; popülasyonun tamamı aynı eski nesilden üretilir.</p></section>}
              {isGsa && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / YERÇEKİMİ DİNAMİĞİ</span><h2>Kütle, kuvvet ve Kbest ajanları</h2></div><span className="surface-pill">GSA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Çekim katsayısı G(t)<strong>{format(frame.gsa_gravity??0,7)}</strong></div><div><span className="abc-phase-dot onlooker"/> Çekime katılan Kbest<strong>{frame.gsa_kbest??0} / {frame.agents.length}</strong></div><div><span className="abc-phase-dot scout"/> Ortalama ivme<strong>{format(frame.gsa_mean_acceleration??0,5)}</strong></div></div><p className="abc-phase-caption">En büyük normalize kütle <strong>{format(frame.gsa_max_mass??0,5)}</strong> · Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong> · Kütleler küçük amaç değeri daha iyi olacak şekilde normalize edilir. Kuvvet bağlantıları önceki neslin konum ve kütlelerinden hesaplanmıştır. Her turda N gerçek değerlendirme yapılır.</p></section>}
              {isSa && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / TAVLAMA DİNAMİĞİ</span><h2>Sıcaklık ve Metropolis kabulü</h2></div><span className="surface-pill">SA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Kabul edilen<strong>{frame.sa_accepted_total??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Kötü aday kabulü<strong>{frame.sa_uphill_accepted_total??0}</strong></div><div><span className="abc-phase-dot scout"/> Reddedilen<strong>{frame.sa_rejected_total??0}</strong></div></div><p className="abc-phase-caption">Sıcaklık <strong>{format(frame.sa_temperature??0,5)}</strong> · Son aday kabul olasılığı <strong>{frame.agents[0]?.sa_accept_probability==null?'Başlangıç':`%${(100*frame.agents[0].sa_accept_probability).toFixed(3)}`}</strong> · Güncel çözüm <strong>{format(frame.current_best,6)}</strong> · En iyi kayıt <strong>{format(frame.best_so_far,6)}</strong> · Gerçek NFE <strong>{frame.function_evaluations}</strong>. Kabul edilmeyen adaylar da değerlendirmeye dahil edilir. Bu algoritmada popülasyon yoktur.</p></section>}
              {isSa && currentRun && <section className="panel convergence-panel"><div className="panel-heading"><div><span className="label-overline">03 / SOĞUMA ANALİZİ</span><h2>Sıcaklık eğrisi ve kararlar</h2></div><span className="meta-inline">Yeşil: kabul · Turuncu: ret</span></div><SaTemperatureChart run={currentRun} index={index}/><div className="chart-bottom"><span><strong>Başlangıç:</strong> {format(config.sa_initial_temperature,2)}</span><span><strong>Şimdi:</strong> {format(frame?.sa_temperature??0,5)}</span><span><strong>Soğuma oranı:</strong> {format(config.sa_cooling_rate,2)}</span></div></section>}
              {isIwo && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / İSTİLACI OT DİNAMİĞİ</span><h2>Tohum saçılımı ve rekabetçi seçilim</h2></div><span className="surface-pill">IWO</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Yeni üretilen tohum<strong>{frame.iwo_seeds_generated??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Yaşayan yeni filiz<strong>{frame.iwo_seeds_survived??0}</strong></div><div><span className="abc-phase-dot scout"/> Rekabette elenen<strong>{frame.iwo_competitive_exclusions??0}</strong></div></div><p className="abc-phase-caption">Popülasyon <strong>{frame.iwo_population_before??0} → {frame.iwo_population_after??0}</strong> (en fazla {config.iwo_max_population}) · Yayılma σ = <strong>{format(frame.iwo_sigma??0,4)}</strong> · Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong>. Yeni filiz çizgileri, hayatta kalan tohumların gerçek ebeveyn konumlarından gelir. Elenen tohumların sayısı NFE'ye dahildir.</p></section>}
              {isSma && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / CİVIK MANTAR DİNAMİĞİ</span><h2>Uyarlamalı geri bildirim ve besin arama</h2></div><span className="surface-pill">SMA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Besine yaklaşan<strong>{frame.sma_approach_count??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Büzülen<strong>{frame.sma_contract_count??0}</strong></div><div><span className="abc-phase-dot scout"/> Yeniden başlayan<strong>{frame.sma_restart_count??0}</strong></div></div><p className="abc-phase-caption">Ortalama uyarlamalı ağırlık <strong>{format(frame.sma_mean_weight??1,4)}</strong> · Salınım sınırı a = <strong>{format(frame.sma_a??0,4)}</strong> · Büzülme sınırı b = <strong>{format(frame.sma_b??0,4)}</strong> · Yeniden başlangıç z = <strong>{format(frame.sma_restart_probability??0,2)}</strong> · Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong>. Son iterasyonda b = 0 olur; bu nedenle bazı bireyler tam orijine büzülür.</p></section>}
              {isSsa && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / SALP ZİNCİRİ DİNAMİĞİ</span><h2>Lider ve takipçi hareketi</h2></div><span className="surface-pill">SSA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Lider / takipçi<strong>1 / {frame.agents.length-1}</strong></div><div><span className="abc-phase-dot onlooker"/> Kontrol katsayısı c₁<strong>{format(frame.ssa_c1??0,6)}</strong></div><div><span className="abc-phase-dot scout"/> Zincir uzunluğu<strong>{format(frame.ssa_chain_length??0,4)}</strong></div></div><p className="abc-phase-caption">Liderin besin kaynağına uzaklığı <strong>{format(frame.ssa_leader_distance??0,5)}</strong>. İlk salp arşivdeki en iyi besin konumuna göre hareket eder. Takipçiler sırasıyla güncellenir: her takipçinin yeni konumu kendi önceki konumu ile bir önceki salpın güncel konumunun ortalamasıdır. Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong>.</p></section>}
              {isBa && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / EKOLOKASYON DİNAMİĞİ</span><h2>Frekans, ses şiddeti ve darbe oranı</h2></div><span className="surface-pill">BA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Global aday<strong>{frame.ba_global_proposals??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Yerel aday<strong>{frame.ba_local_proposals??0}</strong></div><div><span className="abc-phase-dot scout"/> Kabul edilen<strong>{frame.ba_accepted_count??0}</strong></div></div><p className="abc-phase-caption">Ortalama ses şiddeti <strong>{format(frame.ba_mean_loudness??0,4)}</strong> · Ortalama darbe oranı <strong>{format(frame.ba_mean_pulse_rate??0,4)}</strong> · Gerçek NFE <strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong>. Reddedilen adaylar da değerlendirmeye dahildir. Ajan seçerek önerilen hareketi ve karar rastgelelik değerini incele.</p></section>}
              {isWoa && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / BALİNA DAVRANIŞLARI</span><h2>Kuşatma, keşif ve baloncuk ağı</h2></div><span className="surface-pill">WOA</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Spiral hareket<strong>{frame.woa_spiral_count??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Kuşatma<strong>{frame.woa_encircle_count??0}</strong></div><div><span className="abc-phase-dot scout"/> Rastgele keşif<strong>{frame.woa_search_count??0}</strong></div></div><p className="abc-phase-caption">Katsayı a = <strong>{format(frame.woa_a??0,3)}</strong>. Hareket türü ve yönelinen nokta önceki neslin verileriyle hesaplanır. Çizgiler hedefi ve adımların yer değiştirmesini gösterir; kesintisiz fiziksel yüzme rotası değildir. Her turda tam N fonksiyon değerlendirmesi yapılır.</p></section>}
              {isGwo && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / KURT SÜRÜSÜ HİYERARŞİSİ</span><h2>Alfa, beta ve delta liderliği</h2></div><span className="surface-pill">GWO</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Alfa / en iyi kurt<strong>{format(frame.agents.find(a=>a.wolf_role==='alpha')?.fitness??0,5)}</strong></div><div><span className="abc-phase-dot onlooker"/> Kontrol katsayısı a<strong>{format(frame.gwo_a??0,3)}</strong></div><div><span className="abc-phase-dot scout"/> Omega kurt<strong>{frame.agents.filter(a=>a.wolf_role==='omega').length}</strong></div></div><p className="abc-phase-caption">Renkler mevcut popülasyondaki kurt sıralamasını gösterir. Bağlantı çizgilerindeki lider konumları ise bu kareyi hesaplamak için kullanılan <strong>önceki nesil</strong> liderlerinin gerçek konumlarıdır. Her nesilde N yeni amaç fonksiyonu değerlendirmesi yapılır.</p></section>}
              {isMfo && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / GÜVE–ALEV DİNAMİĞİ</span><h2>Spiral hareket ve alev sayısı</h2></div><span className="surface-pill">MFO</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Aktif alev<strong>{frame.flame_count??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Güve sayısı<strong>{frame.agents.length}</strong></div><div><span className="abc-phase-dot scout"/> Gerçek NFE<strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong></div></div><p className="abc-phase-caption">Her güve, sıralamadaki alevi veya son aktif alevi izler. Renkli bağlar kullanılan gerçek hedefleri gösterir; her jenerasyonda N çözüm değerlendirilir. Alev sayısı süreç sonunda bire düşer.</p></section>}
              {isCs && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / GUGUK KUŞU DAVRANIŞI</span><h2>Yuva ve Lévy uçuşu dinamikleri</h2></div><span className="surface-pill">CS</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> Kabul edilen uçuş<strong>{frame.accepted_levy_this_iteration??0}</strong></div><div><span className="abc-phase-dot scout"/> Yenilenen yuva<strong>{frame.abandoned_this_iteration??0}</strong></div><div><span className="abc-phase-dot onlooker"/> Mevcut NFE<strong>{frame.function_evaluations.toLocaleString('tr-TR')}</strong></div></div><p className="abc-phase-caption">Her jenerasyonda N aday yumurta rastgele yuvalarla karşılaştırılır; en kötü yuvalardan pₐ oranında olanlar yeniden oluşturulur. Tüm aday değerlendirmeleri bütçeye dahil edilir; en iyi çözüm arşivi saklanır.</p></section>}
              {isAbc && frame && <section className="panel abc-cycle-panel"><div className="panel-heading"><div><span className="label-overline">02 / KOLONİ DİNAMİĞİ</span><h2>Besin kaynağı faaliyetleri</h2></div><span className="surface-pill">ABC</span></div><div className="abc-phase-grid"><div><span className="abc-phase-dot employed"/> İşçi son işlemi<strong>{frame.agents.filter(a=>a.role==='employed').length}</strong></div><div><span className="abc-phase-dot onlooker"/> Gözlemci son işlemi<strong>{frame.agents.filter(a=>a.role==='onlooker').length}</strong></div><div><span className="abc-phase-dot scout"/> Keşifçi yenilemesi<strong>{frame.scouts_this_iteration??0}</strong></div></div><p className="abc-phase-caption">Bir kaynak bir döngüde birden fazla arı tarafından ziyaret edilebilir. Renkler kaynağa son uygulanan işlem türünü gösterir. Her döngüde {frame.agents.length} işçi + {frame.agents.length} gözlemci aday değerlendirmesi vardır.</p></section>}
              <section className="panel convergence-panel"><div className="panel-heading"><div><span className="label-overline">02 / PERFORMANS ANALİZİ</span><h2>Yakınsama analizi</h2></div><span className="graph-legend"><span/> En iyi arşiv değeri</span></div><Convergence run={currentRun} index={index}/><div className="chart-bottom"><span><strong>Mevcut en iyi:</strong> {frame?format(frame.current_best):'—'}</span><span><strong>Ortalama uygunluk:</strong> {frame?format(frame.mean_fitness):'—'}</span><span><strong>Hesaplama süresi:</strong> {currentRun?`${format(currentRun.duration_ms,1)} ms`:'—'}</span></div></section>
            </div>
            <div className={`lab-right ${paramsOpen?'lab-right-open':''}`}><section className="panel params-panel"><div className="panel-heading"><div><span className="label-overline">KONTROL MERKEZİ</span><h2>Simülasyon ayarları</h2></div><Settings2 size={19} className="panel-heading-icon"/></div>
              <div className="settings-body"><label className="select-label">AMAÇ FONKSİYONU <select value={config.objective} onChange={e=>update('objective',e.target.value)}>{catalog?.objectives.map(o=><option key={o.id} value={o.id}>{o.name}</option>)??<option>Rastrigin</option>}</select></label><p className="function-note">{catalog?.objectives.find(o=>o.id===config.objective)?.description}</p><div className="settings-divider"/>
                {!isSa && <ParameterSlider title="Popülasyon büyüklüğü" hint={isPso?"Parçacık sayısı":isAbc?"Besin kaynağı sayısı (işçi başına bir kaynak)":isCs?"Yuva sayısı":isMfo?"Güve sayısı":isGwo?"Kurt sayısı":isWoa?"Balina sayısı":isBa?"Yarasa sayısı":isSsa?"Salp sayısı":isSma?"Cıvık mantar bireyi sayısı":isIwo?"Başlangıç yabani ot sayısı":isGsa?"Çekimle hareket eden kütle sayısı":isDe?"DE aday çözüm sayısı":"Ateşböceği sayısı"} value={config.population_size} min={5} max={60} step={1} decimals={0} onChange={v=>{update('population_size',v);if(isIwo&&v>config.iwo_max_population)update('iwo_max_population',v)}}/>}
                <ParameterSlider title="İterasyon sayısı" hint="Maksimum jenerasyon" value={config.iterations} min={10} max={250} step={10} decimals={0} onChange={v=>update('iterations',v)}/>
                {isDe ? <>
                  <ParameterSlider title="Mutasyon ölçeği (F)" hint="Fark vektörü (Xr₂−Xr₃) katsayısı" value={config.de_mutation_factor} min={0} max={2} step={.05} onChange={v=>update('de_mutation_factor',v)}/>
                  <ParameterSlider title="Binom çaprazlama oranı (CR)" hint="Her koordinatın mutanttan alınma olasılığı" value={config.de_crossover_rate} min={0} max={1} step={.05} onChange={v=>update('de_crossover_rate',v)}/>
                  <div className="abc-params-note">DE/rand/1/bin: her aday için en az 4 birey gerekir. Donörler birbirinden ve hedeften ayrıdır. Zorunlu jrand ile en az bir koordinat mutanttan gelir. Reddedilen denemeler dahil NFE = N × (T + 1).</div>
                </> : isGsa ? <>
                  <ParameterSlider title="Başlangıç çekimi (G₀)" hint="Kuvvet şiddetinin başlangıç ölçeği" value={config.gsa_initial_gravity} min={1} max={500} step={1} decimals={0} onChange={v=>update('gsa_initial_gravity',v)}/>
                  <ParameterSlider title="Sönüm katsayısı (α)" hint="G(t) = G₀ exp(−α·t/T)" value={config.gsa_decay} min={0} max={40} step={.5} onChange={v=>update('gsa_decay',v)}/>
                  <ParameterSlider title="Mesafe yumuşatması (ε)" hint="R + ε: çok yakın ajanlar için sayısal kararlılık" value={config.gsa_epsilon} min={.001} max={1} step={.001} decimals={3} onChange={v=>update('gsa_epsilon',v)}/>
                  <div className="abc-params-note">Güncel uygunluktan normalize kütleler hesaplanır. Kbest, N'den 1'e azalır. Rastgele ağırlıklı çekim kuvveti önceki neslin noktalarından hesaplanır; v′ = U·v + F/M ve x′ = clip(x + v′). Toplam NFE = N × (T + 1).</div>
                </> : isSa ? <>
                  <ParameterSlider title="Başlangıç sıcaklığı (T₀)" hint="Yüksek sıcaklık kötü adayların kabulünü kolaylaştırır" value={config.sa_initial_temperature} min={.1} max={100} step={.1} onChange={v=>update('sa_initial_temperature',v)}/>
                  <ParameterSlider title="Soğutma oranı (r)" hint="Her tur sıcaklık r ile çarpılır" value={config.sa_cooling_rate} min={.5} max={1} step={.01} onChange={v=>update('sa_cooling_rate',v)}/>
                  <ParameterSlider title="Komşu adım ölçeği (σ)" hint="Koordinat aralığının Gaussian standart sapma oranı" value={config.sa_step_scale} min={.01} max={1} step={.01} onChange={v=>update('sa_step_scale',v)}/>
                  <div className="abc-params-note">SA tek bir güncel çözüm tutar. Her adımda 1 yeni aday ölçülür (NFE = T + 1). Kötü adaylar exp(−Δf/T) olasılığıyla kabul edilebilir; arşivdeki en iyi sonuç asla kötüleşmez.</div>
                </> : isIwo ? <>
                  <ParameterSlider title="Maksimum koloni büyüklüğü" hint="Rekabetten sonra kalan en çok bitki" value={Math.max(config.population_size,config.iwo_max_population)} min={config.population_size} max={100} step={1} decimals={0} onChange={v=>update('iwo_max_population',v)}/>
                  <ParameterSlider title="Minimum tohum" hint="En zayıf bireyin üreteceği en az tohum" value={config.iwo_min_seeds} min={0} max={config.iwo_max_seeds} step={1} decimals={0} onChange={v=>update('iwo_min_seeds',v)}/>
                  <ParameterSlider title="Maksimum tohum" hint="En iyi bireyin üretim kapasitesi" value={config.iwo_max_seeds} min={config.iwo_min_seeds} max={8} step={1} decimals={0} onChange={v=>update('iwo_max_seeds',v)}/>
                  <ParameterSlider title="Başlangıç dağılımı (σ₀)" hint="Başlangıçta tohum saçılma standart sapması" value={config.iwo_sigma_initial} min={config.iwo_sigma_final} max={5} step={.01} onChange={v=>update('iwo_sigma_initial',v)}/>
                  <ParameterSlider title="Son dağılım (σₛ)" hint="Son jenerasyondaki standart sapma" value={config.iwo_sigma_final} min={.01} max={Math.min(1,config.iwo_sigma_initial)} step={.01} onChange={v=>update('iwo_sigma_final',v)}/>
                  <ParameterSlider title="Azalma üssü (m)" hint="Tohum dağılımının doğrusal olmayan daralması" value={config.iwo_modulation_index} min={1} max={6} step={.1} onChange={v=>update('iwo_modulation_index',v)}/>
                  <div className="abc-params-note">Her bitki uygunluğuna göre tohum üretir. Tohumlar N(0,σ²) ile saçılır; ebeveynler ve yavrular birlikte yarışır. NFE her yeni tohum için bir artar; popülasyon büyüklüğü sabit değildir.</div>
                </> : isSma ? <>
                  <ParameterSlider title="Rastgele yeniden başlangıç olasılığı (z)" hint="Standart SMA değeri 0,03; keşif için yeniden konumlandırma" value={config.sma_restart_probability} min={0} max={1} step={.01} onChange={v=>update('sma_restart_probability',v)}/>
                  <div className="abc-params-note">Yaklaşma olasılığı p ve uyarlamalı W her tur güncellenir; a ve b zamanla azalır. Üç hareketten yalnızca biri her birey için değerlendirilir: gerçek NFE = N × (T + 1).</div>
                </> : isSsa ? <>
                  <ParameterSlider title="Başlangıç keşif katsayısı (c₁₀)" hint="Standart SSA değeri 2,0; tur boyunca üstel olarak azalır" value={config.ssa_c1_initial} min={.25} max={3} step={.05} onChange={v=>update('ssa_c1_initial',v)}/>
                  <div className="abc-params-note">Lider: F ± c₁[(ub−lb)c₂+lb]; c₁(t)=c₁₀·exp(−(4t/T)²). Takipçi: xᵢ′=(xᵢ eski + xᵢ₋₁ yeni)/2. Pozisyonlar sınırlara kırpılır; her jenerasyonda N gerçek değerlendirme yapılır.</div>
                </> : isBa ? <>
                  <ParameterSlider title="En düşük frekans (fₘᵢₙ)" hint="Hız güncellemesinin frekans aralığı alt sınırı" value={config.ba_frequency_min} min={0} max={2} step={.05} onChange={v=>update('ba_frequency_min',Math.min(v,config.ba_frequency_max))}/>
                  <ParameterSlider title="En yüksek frekans (fₘₐₓ)" hint="Rastgele örneklenen frekans aralığı üst sınırı" value={config.ba_frequency_max} min={.1} max={5} step={.05} onChange={v=>update('ba_frequency_max',Math.max(v,config.ba_frequency_min))}/>
                  <ParameterSlider title="Başlangıç ses şiddeti (A₀)" hint="Daha iyi adayı kabul etme eşiği" value={config.ba_initial_loudness} min={.05} max={1} step={.05} onChange={v=>update('ba_initial_loudness',v)}/>
                  <ParameterSlider title="Ses şiddeti azalma (α)" hint="Kabul edilen çözüm sonrası A ← αA" value={config.ba_loudness_decay} min={.1} max={1} step={.05} onChange={v=>update('ba_loudness_decay',v)}/>
                  <ParameterSlider title="Darbe oranı üst sınırı (r₀)" hint="Yerel arama olasılığını kontrol eder" value={config.ba_initial_pulse_rate} min={0} max={1} step={.05} onChange={v=>update('ba_initial_pulse_rate',v)}/>
                  <ParameterSlider title="Darbe artış katsayısı (γ)" hint="r₀(1−exp(−γ·t)) geçiş hızı" value={config.ba_pulse_growth} min={.1} max={5} step={.05} onChange={v=>update('ba_pulse_growth',v)}/>
                  <div className="abc-params-note">Her yarasa adım başına bir yeni aday değerlendirir; reddedilen adaylar da gerçek NFE'ye dahildir. Kabul edilen adımda ses şiddeti azalır, darbe oranı yükselir. Toplam NFE = N × (T + 1).</div>
                </> : isWoa ? <>
                  <ParameterSlider title="Başlangıç kuşatma katsayısı (a₀)" hint="Varsayılan 2.0; son adımda sıfıra iner" value={config.woa_initial_a} min={.25} max={3} step={.05} onChange={v=>update('woa_initial_a',v)}/>
                  <ParameterSlider title="Spiral şekil katsayısı (b)" hint="Baloncuk-ağı spiral üstel katsayısı" value={config.woa_spiral_b} min={.1} max={3} step={.05} onChange={v=>update('woa_spiral_b',v)}/>
                  <ParameterSlider title="Spiral hareket olasılığı" hint="Varsayılan 0.50; kalan pay kuşatma veya keşiftir" value={config.woa_spiral_probability} min={0} max={1} step={.05} onChange={v=>update('woa_spiral_probability',v)}/>
                  <div className="abc-params-note">Her balina her adımda tek aday üretir. Spiral, en iyiyi kuşatma veya başka balinaya göre keşif hareketi gerçek katsayılarla hesaplanır; NFE = N × (T + 1).</div>
                </> : isGwo ? <>
                  <ParameterSlider title="Başlangıç kuşatma katsayısı (a₀)" hint="Varsayılan 2.0; iterasyonlar boyunca sıfıra iner" value={config.gwo_initial_a} min={.25} max={3} step={.05} onChange={v=>update('gwo_initial_a',v)}/>
                  <div className="abc-params-note">Alfa–beta–delta güncel en iyi üç kurttur. Her yeni konum bu üç liderin bağımsız kuşatma adaylarının ortalamasıdır. a₀=2 standart başlangıç değeri, diğer değerler deneysel parametre varyantıdır. NFE = N × (T + 1).</div>
                </> : isMfo ? <>
                  <ParameterSlider title="Spiral şekil katsayısı (b)" hint="Logaritmik spiral üstel katsayısı" value={config.mfo_spiral_b} min={.1} max={3} step={.05} onChange={v=>update('mfo_spiral_b',v)}/>
                  <div className="abc-params-note">Her jenerasyon N yeni güve konumu değerlendirir. Alev sayısı round(N−l(N−1)/T) ile kademeli olarak 1'e düşer. Güveler sıraya göre alev belleğini izler.</div>
                </> : isCs ? <>
                  <ParameterSlider title="Keşif / terk oranı (pₐ)" hint="En kötü yuvalardan yenilenecek pay" value={config.cs_discovery_rate} min={0} max={1} step={.01} onChange={v=>update('cs_discovery_rate',v)}/>
                  <ParameterSlider title="Lévy adım ölçeği" hint="Rastgele sıçramanın büyüklüğü" value={config.cs_step_scale} min={.005} max={.5} step={.005} decimals={3} onChange={v=>update('cs_step_scale',v)}/>
                  <ParameterSlider title="Lévy üssü (β)" hint="Ağır kuyruk parametresi (Mantegna)" value={config.cs_levy_exponent} min={1.1} max={1.9} step={.05} onChange={v=>update('cs_levy_exponent',v)}/>
                  <div className="abc-params-note">Her jenerasyon: N Lévy denemesi + en kötü round(pₐ × N) yuvanın yenilenmesi. NFE, ilk popülasyon ve reddedilenler dahil gerçek hesap sayısıdır.</div>
                </> : isAbc ? <>
                  <ParameterSlider title="Terk etme limiti" hint="İyileşmeyen kaynağın keşifçiye dönüşme eşiği" value={config.abc_limit} min={1} max={200} step={1} decimals={0} onChange={v=>update('abc_limit',v)}/>
                  <div className="abc-params-note">Döngü başına N işçi ve N gözlemci aday değerlendirmesi yapılır. Keşifçi devreye girdiğinde gerçek NFE artar.</div>
                </> : isPso ? <>
                  <ParameterSlider title="Atalet (w)" hint="Önceki hızın ağırlığı" value={config.inertia_weight} min={0} max={1.2} step={.01} onChange={v=>update('inertia_weight',v)}/>
                  <ParameterSlider title="Bilişsel katsayı (c₁)" hint="Kişisel en iyiye yönelim" value={config.cognitive_coefficient} min={0} max={4} step={.01} onChange={v=>update('cognitive_coefficient',v)}/>
                  <ParameterSlider title="Sosyal katsayı (c₂)" hint="Sürünün en iyisine yönelim" value={config.social_coefficient} min={0} max={4} step={.01} onChange={v=>update('social_coefficient',v)}/>
                  <ParameterSlider title="Hız sınırı" hint="Arama alanı genişliğinin oranı" value={config.velocity_limit} min={.01} max={1} step={.01} onChange={v=>update('velocity_limit',v)}/>
                </> : <>
                  <ParameterSlider title="Alpha (α)" hint="Rassal hareket katsayısı" value={config.alpha} min={0} max={1} step={.01} onChange={v=>update('alpha',v)}/>
                  <ParameterSlider title="Beta (β₀)" hint="Başlangıç çekiciliği" value={config.beta0} min={0} max={3} step={.05} onChange={v=>update('beta0',v)}/>
                  <ParameterSlider title="Gamma (γ)" hint="Işığın soğurulma oranı" value={config.gamma} min={0} max={5} step={.01} onChange={v=>update('gamma',v)}/>
                </>}
                <div className="seed-row"><label htmlFor="seed">RASTGELE TOHUM <small>Tekrarlanabilir deney</small></label><input id="seed" type="number" min={0} max={2147483647} step={1} value={config.seed} onChange={e=>update('seed',Math.max(0,Math.min(2147483647,Math.round(Number(e.target.value)||0))))}/></div>
                {stale && <div className="stale-warning"><RotateCcw size={14}/> Ayarlar değiştirildi. Yeni sonuçlar için tekrar çalıştır.</div>}
                <button className="button-primary start-btn" disabled={loading} onClick={start}>{loading?<span className="spinner"/>:<Play size={17} fill="currentColor"/>}{loading?'Hesaplanıyor...':'Simülasyonu çalıştır'}<ArrowRight size={16}/></button>
                <div className="output-actions"><button onClick={()=>{if(currentRun)downloadJson(currentRun,`${currentRun.algorithm}-${currentRun.objective}-${currentRun.seed}.json`)}} disabled={!currentRun}><ArrowDownToLine size={15}/> JSON</button><button onClick={exportCsv} disabled={!currentRun}><ArrowDownToLine size={15}/> CSV</button></div>
              </div></section>
              <div className="method-note"><span className="note-spot"><Check size={13}/></span><div><strong>Gerçek hesaplama verileri</strong><p>Animasyondaki konumlar FastAPI üzerinden Python optimizasyon motorunun hesapladığı her iterasyonun kayıtlarıdır. Grafik ve metrikler aynı veriyi kullanır.</p></div></div>
            </div>
          </div>
          <section className="panel knowledge-strip"><div className="knowledge-icon"><BookOpen size={23}/></div><div><span className="label-overline">ALGORİTMAYI ANLA</span><h3>{isPso?'Parçacıklar en iyi çözümü nasıl buluyor?':isAbc?'Arılar hangi besin kaynaklarını seçiyor?':isCs?'Guguk kuşları hangi yuvaları değiştiriyor?':isMfo?'Güveler hangi alevleri izliyor?':isGwo?'Alfa, beta ve delta kurtları avı nasıl kuşatıyor?':isWoa?'Balinalar spiral ve kuşatma hareketi arasında nasıl geçiş yapıyor?':isBa?'Yarasalar frekans, ses şiddeti ve darbe oranıyla nasıl arıyor?':isSsa?'Salp sürüsünde lider ve takipçiler nasıl hareket ediyor?':isSma?'Cıvık mantarlar besin kokusuna göre nasıl yönleniyor?':isIwo?'Yabani otlar nasıl tohum üretip alanı kolonize ediyor?':isSa?'Tavlama neden bazen daha kötü çözümü kabul ediyor?':isGsa?'Kütleler birbirlerini hangi kuvvetle çekiyor?':isDe?'Vektör farkları yeni adayları nasıl oluşturuyor?':'Ateşböcekleri en iyi çözümü nasıl buluyor?'}</h3><p>{isPso?'Atalet, kişisel en iyi, sürü en iyisi ve hız vektörlerini denklemleriyle keşfet.':isAbc?'İşçi, gözlemci ve keşifçi aşamalarını; nektar olasılığını, deneme sayacını ve kaynak yenilemeyi incele.':isCs?'Lévy dağılımı, ev sahibi yuva seçimi, kabul ve terk etme aşamalarını gerçek NFE ile incele.':isMfo?'Azalan alev sayısını ve her güve için hesaplanan logaritmik spiral hareketini incele.':isGwo?'Üç liderden hesaplanan kuşatma adaylarını, azalan a katsayısını ve sürü hiyerarşisini incele.':isWoa?'Av konumunu, rastgele akran keşfini, A/C katsayılarını ve baloncuk ağı spiralini denklemlerle incele.':isBa?'Hız vektörü, frekans ve yerel aramayı; kabul ve ret kararlarını gerçek aday kayıtlarıyla incele.':isSsa?'Besin kaynağı, üstel c₁ azalması ve sıralı zincir güncellemesinin kayıtlı katsayılarını incele.':isSma?'Uyarlamalı W ağırlıklarını, p karar olasılığını ve yaklaşma/büzülme/yeniden başlangıç hareketlerini incele.':isIwo?'Uygunluğa bağlı tohum sayısını, değişken popülasyonu, azalan σ değerini ve rekabette elenenleri gerçek fonksiyon değerlendirmeleriyle izle.':isSa?'Sıcaklık düşüşünü, kötü aday kabul olasılığını ve reddedilen komşu noktaları matematiksel kayıtlarla incele.':isGsa?'Normalize kütleleri, azalan yerçekimi katsayısını, Kbest ve hız/ivme denklemlerini kayıtlı verilerle incele.':isDe?'Donör seçimi, fark mutasyonu, çaprazlama maskesi ve açgözlü seçimi kayıtlı vektörlerle incele.':'Işık yoğunluğu, mesafe etkisi, rassal keşif ve global en iyi arşivi arasındaki ilişkiyi denklemleriyle birlikte incele.'}</p></div><button className="button-subtle" onClick={()=>{setTab('learn');setPlaying(false)}}>Modeli keşfet <ArrowRight size={15}/></button></section>
        </>}
        </Suspense></ModuleErrorBoundary>
        <footer className="site-footer"><span>© 2026 Metaheuristic Lab · Araştırma ve eğitim amaçlı optimizasyon laboratuvarı</span><span>CONTINUOUS + DISCRETE LAB <span>•</span> v{APP_VERSION}</span></footer>
      </main>
    </div>
    {tab==='sim'&&ready&&activeId!=='aco'&&<button className="mobile-settings-toggle" onClick={()=>setParamsOpen(!paramsOpen)}><Settings2 size={18}/>{paramsOpen?'Ayarları gizle':'Parametreler'}</button>}
  </div>;
}
